<script setup>
import { onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { getSessions, getPublicSession, getSessionStats, previousSession, nextSession } from '../api/client'
const route = useRoute(); const session = ref(null); const publicState = ref(null); const stats = ref(null); const errorMessage = ref(''); const navigatingAction = ref(''); let timer; let loading = false
async function load() { if (loading) return; loading = true; try { if (!session.value) { const sessions = await getSessions(); session.value = sessions.find(x => x.id === route.params.id) } if (session.value) { publicState.value = await getPublicSession(session.value.access_token); session.value = { ...session.value, status: publicState.value.status }; stats.value = await getSessionStats(session.value.id); if (session.value.status === 'closed') clearInterval(timer) } errorMessage.value = '' } catch (e) { if (!session.value) errorMessage.value = e.message } finally { loading = false } }
async function action(fn, direction) { if (navigatingAction.value) return; navigatingAction.value = direction; errorMessage.value = ''; try { await fn(route.params.id); await load() } catch (e) { errorMessage.value = e.message } finally { navigatingAction.value = '' } }
onMounted(async () => { await load(); if (session.value?.status !== 'closed') timer = setInterval(load, 2000) }); onUnmounted(() => clearInterval(timer))
</script>
<template><main class="app-shell"><header class="topbar"><div><RouterLink class="back-link-inline" to="/teacher">← 返回老师工作台</RouterLink><p class="eyebrow">LIVE CLASSROOM</p><h1>课堂控制台</h1></div></header><p v-if="errorMessage" class="error-message">{{ errorMessage }}</p><section v-if="session" class="detail-panel"><div class="session-status"><span class="status-pill">{{ session.status === 'active' ? '进行中' : session.status === 'closed' ? '已结束' : session.status }}</span><span>已加入 {{ stats?.participant_count || 0 }} 人 · 已提交 {{ stats?.submitted_count || 0 }} 人</span></div><div v-if="session.status === 'closed'" class="completion-message"><h2>所有题目已经播放完毕</h2><p>课堂答题已经结束，请前往「即时统计」查看学生的提交分布和正确情况。</p><RouterLink class="primary-button inline-button" to="/teacher/reports">前往即时统计</RouterLink></div><div v-else-if="publicState?.question" class="live-question"><p class="eyebrow">当前题目 {{ publicState.question.sort_order }}</p><img v-if="publicState.question.question_image_url" class="question-image" :src="publicState.question.question_image_url" alt="题目图片" /><h2 v-if="publicState.question.question_text">{{ publicState.question.question_text }}</h2><div class="option-preview-grid"><span v-for="option in publicState.question.options" :key="option.id"><strong>{{ option.option_key }}.</strong><img v-if="option.option_image_url" class="option-image" :src="option.option_image_url" alt="选项图片" /><template v-else>{{ option.option_text }}</template></span></div></div><div v-else class="empty-state">正在读取当前题目…</div><div v-if="session.status === 'active'" class="distribution"><div v-for="key in ['A','B','C','D']" :key="key"><strong>{{ key }}</strong><span>{{ stats?.distribution?.[key] || 0 }}</span></div></div><div v-if="session.status === 'active'" class="button-row"><button class="secondary-button" :disabled="Boolean(navigatingAction) || publicState?.question?.sort_order <= 1" @click="action(previousSession, 'previous')"><span v-if="navigatingAction === 'previous'" class="loading-spinner" aria-hidden="true"></span>{{ navigatingAction === 'previous' ? '切换中…' : '上一题' }}</button><button class="primary-button" :disabled="Boolean(navigatingAction)" @click="action(nextSession, 'next')"><span v-if="navigatingAction === 'next'" class="loading-spinner" aria-hidden="true"></span>{{ navigatingAction === 'next' ? '切换中…' : '下一题' }}</button></div></section></main></template>
